package com.kalai73.lifemapp.widgets.core.designsystem

/**
 * Predator shapes (styleguide §5.2) as white masks, tinted at render time. A frame is the outer mask in
 * the edge color with the 1dp-inset inner mask in the fill color on top. Generated by
 * scratchpad/gen_predator_shapes.py: cuts and slants keep their dp size at any widget size.
 */
enum class PdShape(val outer: Int, val inner: Int) {
    /** Widget panel: cut 12, fill cut 14 so the accent corner diagonals read thicker. */
    CHAMFER_LG(R.drawable.pd_chamfer_lg, R.drawable.pd_chamfer_lg_inner),
    /** Rows, tiles, icon buttons: cut 6. */
    CHAMFER_SM(R.drawable.pd_chamfer_sm, R.drawable.pd_chamfer_sm_inner),
    /** Buttons, chips, tags: slant 8. */
    PARA(R.drawable.pd_para, R.drawable.pd_para_inner),
    /** Hero banner pointing right. */
    ARROW(R.drawable.pd_arrow, R.drawable.pd_arrow_inner),
    /** Pointy-top hexagon, 1 : 1.1. */
    HEX(R.drawable.pd_hex, R.drawable.pd_hex_inner),
}

object PdDrawables {
    /** Accent on the two cut corners of [PdShape.CHAMFER_LG] and 8dp of the adjoining edges. */
    val CHAMFER_LG_CORNERS = R.drawable.pd_chamfer_lg_corners
    /** Color bar leaning −12°. */
    val BAR = R.drawable.pd_bar
    /** 1px divider leaning −18°. */
    val DIVIDER = R.drawable.pd_divider
    /** Square checkbox. */
    val CHECK_SQUARE = R.drawable.pd_check_square
}
